// Item is a single stored item.
type Item struct {
	ID   string    `json:"id"`
	Name string    `json:"name"`
}

// Store is a thread-safe in-memory item store.
type Store struct {
	mu     sync.Mutex
	items  []Item
	nextID int
}

func NewStore() *Store {
	return &Store{}
}

func (s *Store) Create(name string) Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nextID++
	item := Item{
		ID:   strconv.Itoa(s.nextID),
		Name: name,
	}
	s.items = append(s.items, item)
	return item
}

func (s *Store) List() []Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	// Return a copy to avoid races if the caller mutates it.
	out := make([]Item, len(s.items))
	copy(out, s.items)
	return out
}
